CREATE TABLE delivery_quotes(id UUID PRIMARY KEY,requester_id UUID NOT NULL,pickup_address VARCHAR(250) NOT NULL,pickup_latitude DOUBLE PRECISION NOT NULL CHECK(pickup_latitude BETWEEN -90 AND 90),pickup_longitude DOUBLE PRECISION NOT NULL CHECK(pickup_longitude BETWEEN -180 AND 180),dropoff_address VARCHAR(250) NOT NULL,dropoff_latitude DOUBLE PRECISION NOT NULL CHECK(dropoff_latitude BETWEEN -90 AND 90),dropoff_longitude DOUBLE PRECISION NOT NULL CHECK(dropoff_longitude BETWEEN -180 AND 180),package_description VARCHAR(500) NOT NULL,distance_meters BIGINT NOT NULL CHECK(distance_meters>0),amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency VARCHAR(3) NOT NULL,expires_at TIMESTAMPTZ NOT NULL,consumed_at TIMESTAMPTZ,is_deleted BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(200),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_by VARCHAR(200),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_delivery_quotes_requester_created ON delivery_quotes(requester_id,created_at DESC);
CREATE TABLE delivery_quotes_aud(id UUID NOT NULL,rev INTEGER NOT NULL,revtype SMALLINT,requester_id UUID,pickup_address VARCHAR(250),pickup_latitude DOUBLE PRECISION,pickup_longitude DOUBLE PRECISION,dropoff_address VARCHAR(250),dropoff_latitude DOUBLE PRECISION,dropoff_longitude DOUBLE PRECISION,package_description VARCHAR(500),distance_meters BIGINT,amount_minor BIGINT,currency VARCHAR(3),expires_at TIMESTAMPTZ,consumed_at TIMESTAMPTZ,version BIGINT,created_by VARCHAR(200),created_at TIMESTAMPTZ,updated_by VARCHAR(200),updated_at TIMESTAMPTZ,PRIMARY KEY(id,rev));
CREATE TABLE delivery_requests(id UUID PRIMARY KEY,quote_id UUID NOT NULL UNIQUE REFERENCES delivery_quotes(id),requester_id UUID NOT NULL,payment_intent_id UUID UNIQUE,amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency VARCHAR(3) NOT NULL,distance_meters BIGINT NOT NULL CHECK(distance_meters>0),pickup_address VARCHAR(250) NOT NULL,pickup_latitude DOUBLE PRECISION NOT NULL CHECK(pickup_latitude BETWEEN -90 AND 90),pickup_longitude DOUBLE PRECISION NOT NULL CHECK(pickup_longitude BETWEEN -180 AND 180),dropoff_address VARCHAR(250) NOT NULL,dropoff_latitude DOUBLE PRECISION NOT NULL CHECK(dropoff_latitude BETWEEN -90 AND 90),dropoff_longitude DOUBLE PRECISION NOT NULL CHECK(dropoff_longitude BETWEEN -180 AND 180),package_description VARCHAR(500) NOT NULL,status VARCHAR(32) NOT NULL CHECK(status IN('AWAITING_PAYMENT','PAYMENT_FAILED','READY_FOR_DISPATCH','ASSIGNED','PICKED_UP','IN_TRANSIT','DELIVERED','FAILED','CANCELLED','RETURNED')),proof_code_hash VARCHAR(64) NOT NULL,courier_name VARCHAR(120),courier_phone VARCHAR(80),failure_reason VARCHAR(500),delivered_at TIMESTAMPTZ,is_deleted BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(200),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_by VARCHAR(200),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT delivery_delivered_evidence_chk CHECK(status<>'DELIVERED' OR delivered_at IS NOT NULL));
CREATE INDEX idx_delivery_requests_requester_created ON delivery_requests(requester_id,created_at DESC);
CREATE INDEX idx_delivery_requests_status_created ON delivery_requests(status,created_at DESC);
CREATE TABLE delivery_requests_aud(id UUID NOT NULL,rev INTEGER NOT NULL,revtype SMALLINT,quote_id UUID,requester_id UUID,payment_intent_id UUID,amount_minor BIGINT,currency VARCHAR(3),distance_meters BIGINT,pickup_address VARCHAR(250),pickup_latitude DOUBLE PRECISION,pickup_longitude DOUBLE PRECISION,dropoff_address VARCHAR(250),dropoff_latitude DOUBLE PRECISION,dropoff_longitude DOUBLE PRECISION,package_description VARCHAR(500),status VARCHAR(32),proof_code_hash VARCHAR(64),courier_name VARCHAR(120),courier_phone VARCHAR(80),failure_reason VARCHAR(500),delivered_at TIMESTAMPTZ,version BIGINT,created_by VARCHAR(200),created_at TIMESTAMPTZ,updated_by VARCHAR(200),updated_at TIMESTAMPTZ,PRIMARY KEY(id,rev));
CREATE TABLE delivery_request_events(id UUID PRIMARY KEY,delivery_request_id UUID NOT NULL REFERENCES delivery_requests(id),actor_id UUID,from_status VARCHAR(32),to_status VARCHAR(32) NOT NULL,reason VARCHAR(500),occurred_at TIMESTAMPTZ NOT NULL,is_deleted BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(200),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_by VARCHAR(200),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_delivery_request_events_request_time ON delivery_request_events(delivery_request_id,occurred_at);
CREATE TABLE delivery_request_events_aud(id UUID NOT NULL,rev INTEGER NOT NULL,revtype SMALLINT,delivery_request_id UUID,actor_id UUID,from_status VARCHAR(32),to_status VARCHAR(32),reason VARCHAR(500),occurred_at TIMESTAMPTZ,version BIGINT,created_by VARCHAR(200),created_at TIMESTAMPTZ,updated_by VARCHAR(200),updated_at TIMESTAMPTZ,PRIMARY KEY(id,rev));
CREATE TABLE ledger_journal_postings(id UUID PRIMARY KEY,source_type VARCHAR(24) NOT NULL CHECK(source_type='DELIVERY'),source_id UUID NOT NULL,payment_intent_id UUID NOT NULL,operation_key VARCHAR(80) NOT NULL,debit_account VARCHAR(40) NOT NULL CHECK(debit_account IN('PSP_CLEARING','DELIVERY_CUSTOMER_ADVANCES','DELIVERY_REVENUE','DELIVERY_REFUNDS')),credit_account VARCHAR(40) NOT NULL CHECK(credit_account IN('PSP_CLEARING','DELIVERY_CUSTOMER_ADVANCES','DELIVERY_REVENUE','DELIVERY_REFUNDS')),amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency VARCHAR(3) NOT NULL,cumulative_refund_minor BIGINT,memo VARCHAR(500) NOT NULL,is_deleted BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(200),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_by VARCHAR(200),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT ledger_journal_accounts_differ_chk CHECK(debit_account<>credit_account),CONSTRAINT ledger_journal_source_operation_uq UNIQUE(source_type,source_id,operation_key),CONSTRAINT ledger_journal_refund_total_chk CHECK((operation_key LIKE 'REFUND:%' AND cumulative_refund_minor>0) OR (operation_key NOT LIKE 'REFUND:%' AND cumulative_refund_minor IS NULL)));
CREATE INDEX idx_ledger_journal_source ON ledger_journal_postings(source_type,source_id);
CREATE INDEX idx_ledger_journal_payment ON ledger_journal_postings(payment_intent_id);
CREATE TABLE ledger_journal_postings_aud(id UUID NOT NULL,rev INTEGER NOT NULL,revtype SMALLINT,source_type VARCHAR(24),source_id UUID,payment_intent_id UUID,operation_key VARCHAR(80),debit_account VARCHAR(40),credit_account VARCHAR(40),amount_minor BIGINT,currency VARCHAR(3),cumulative_refund_minor BIGINT,memo VARCHAR(500),version BIGINT,created_by VARCHAR(200),created_at TIMESTAMPTZ,updated_by VARCHAR(200),updated_at TIMESTAMPTZ,PRIMARY KEY(id,rev));
ALTER TABLE payment_intents ADD COLUMN delivery_request_id UUID;
ALTER TABLE payment_intents ADD CONSTRAINT payment_intents_delivery_request_id_unique UNIQUE(delivery_request_id);
ALTER TABLE payment_intents DROP CONSTRAINT chk_payment_intents_origin;
ALTER TABLE payment_intents ADD CONSTRAINT chk_payment_intents_origin CHECK(origin IN('BOOKING','AD','ORDER','LOAN','DELIVERY')) NOT VALID;
ALTER TABLE payment_intents DROP CONSTRAINT ck_payment_intents_origin_pairing;
ALTER TABLE payment_intents ADD CONSTRAINT ck_payment_intents_origin_pairing CHECK((origin='BOOKING' AND booking_id IS NOT NULL AND ad_campaign_id IS NULL AND order_id IS NULL AND loan_id IS NULL AND delivery_request_id IS NULL) OR (origin='AD' AND booking_id IS NULL AND ad_campaign_id IS NOT NULL AND order_id IS NULL AND loan_id IS NULL AND delivery_request_id IS NULL) OR (origin='ORDER' AND booking_id IS NULL AND ad_campaign_id IS NULL AND order_id IS NOT NULL AND loan_id IS NULL AND delivery_request_id IS NULL) OR (origin='LOAN' AND booking_id IS NULL AND ad_campaign_id IS NULL AND order_id IS NULL AND loan_id IS NOT NULL AND delivery_request_id IS NULL) OR (origin='DELIVERY' AND booking_id IS NULL AND ad_campaign_id IS NULL AND order_id IS NULL AND loan_id IS NULL AND delivery_request_id IS NOT NULL)) NOT VALID;
ALTER TABLE payment_intents_aud ADD COLUMN delivery_request_id UUID;
